// because an empty id builds the bare prefix as a *target*; nothing here builds
// one, and Store.SetName already answers ErrSessionNotFound for an id it does not
// hold. A guard added here would be a branch no test could tell from the one
// below it.
func (m *Manager) Rename(s Session, name string) (Session, error) {
	if err := ValidateName(name); err != nil {
		return Session{}, fmt.Errorf("rename session %s: %w", s.ID, err)
	}

	if err := m.store.SetName(s.ID, name); err != nil {
		return Session{}, fmt.Errorf("rename session %s: %w", s.ID, err)
	}
	// The caller's copy carries the field this call just wrote, the way Resolve
	// carries the one it wrote: re-reading the store would cost a second lock for
	// the single field this method is the writer of.
	s.Name = name

	// Beside the store mutation rather than in the handler that asked for one,
	// like every other emit here. No record entered or left, and the card an open
	// page is drawing is wrong all the same — it shows a label the daemon no
	// longer holds, which is a fleet change by the only definition that matters.
	m.emit(FleetChanged, s)
	return s, nil
}

// Prompt delivers caller text into a session verbatim and submits it (FR-030).
//
// The record is the one Resolve returned, so ownership, the credential, and the
// deadline have already been settled and the target derives from its ID alone
// (FR-034). Prompt takes the record rather than an ID for exactly that reason:
// there is no second lookup here to disagree with the first, and no path by
// which a caller's spelling of an ID could name a window.
//
// Two commands, in this order and no other. Paste writes the bytes to a tmux
// buffer over stdin, so the payload never becomes part of a command line
// (FR-029) — research D4 is the reason this is not send-keys -l, which drops a
// trailing unescaped ";" from caller text before -l ever applies. The Return
// that follows is a daemon-authored key constant and travels the way the Claude
// start command does. Nothing escapes, quotes, or inspects the text: it is data.
//
// A failure leaves the text where it fell. The buffer paste-buffer -d would have
// deleted may survive a failed submit, which is prompt text sitting in a named
// tmux buffer another client could read — the caller is told the prompt did not
// land, and the buffer is overwritten by the next prompt to the same session.
func (m *Manager) Prompt(ctx context.Context, s Session, text string) error {
	// Unreachable behind the resolver, and refused rather than trusted: an empty
	// ID would build the bare prefix as a target, and a dead session's window is
	// already gone. Both fail closed here so that a future caller reaching this
	// method with a hand-made record cannot type into whatever that names.
	if s.ID == "" {
		return fmt.Errorf("prompt session: %w", ErrSessionNotFound)
	}
	if s.State == StateDead {
		return fmt.Errorf("prompt session %s: %w", s.ID, ErrSessionDead)
	}
	if text == "" {
		return fmt.Errorf("prompt session %s: %w", s.ID, ErrEmptyPrompt)
	}

	unlock := m.lockSession(s.ID)
	defer unlock()

	name := s.TmuxName()

	// The error deliberately names the session and nothing else. Prompt text is
	// secret under docs/security.md §3, so it may not travel back to a caller in
	// an error string any more than it may reach the trail (FR-042).
	if err := m.paste(ctx, s, []byte(text)); err != nil {
		return fmt.Errorf("paste the prompt into session %s: %w", s.ID, err)
	}
	if err := m.tmux.SendKeys(ctx, name, enterKey); err != nil {
		return fmt.Errorf("submit the prompt in session %s: %w", s.ID, err)
	}
	return nil
}

// specOf is the harness facts for a session, derived from its configured start
// command each time (research D1). A name the operator has since removed reads
// as Other, whose spec asks for nothing special.
func (m *Manager) specOf(s Session) harness.Spec {
	// An adopted session that recorded no start-command name has no known
	// harness: labelling it with whatever the default is now would be a guess.
	if s.Adopted && s.StartCommand == "" {
		return harness.For(harness.Other)
	}
	name := s.StartCommand
	if name == "" {
		name = config.DefaultStartCommandName
	}
	cmd, err := m.resolveStartCommand(name)
	if err != nil {
		return harness.For(harness.Other)
	}
	return harness.For(harness.Of(cmd))
}

// SpecOf is specOf for callers outside the package.
func (m *Manager) SpecOf(s Session) harness.Spec { return m.specOf(s) }

// paste delivers a payload the way the session's harness submits it: Codex
// swallows the Enter after a plain paste (research M3), so it gets a bracketed
// one. It serves Prompt and Compact only. Type is bracketed for every harness
// and must not route through here, because Claude's BracketedPaste is false.
func (m *Manager) paste(ctx context.Context, s Session, payload []byte) error {
	if m.specOf(s).BracketedPaste {
		return m.tmux.PasteBracketed(ctx, s.TmuxName(), payload)
	}
	return m.tmux.Paste(ctx, s.TmuxName(), payload)
}

// token's life is not possible without shortening the session's.
func (s Session) TokenExpiry() time.Time { return s.AbsoluteDeadline() }

var (
	// ErrSessionNotFound is returned for an unknown ID *and* for a session
	// owned by someone else, deliberately indistinguishably (FR-033). A handler
	// that cannot tell the two apart cannot leak the difference, which is what
	// keeps session IDs unenumerable without every call site remembering to be
	// careful.
	ErrSessionNotFound = errors.New("session not found")

	// ErrSessionExists guards the one-record-per-ID invariant. Reaching it
	// means either a repeat adoption or a collision in NewID, and both want a
	// loud failure rather than a silently replaced record — the record being
	// overwritten holds the token hash its owner is holding the token for.
	ErrSessionExists = errors.New("session already exists")

	// ErrTooManySessions refuses a create that would put the daemon over
	// CRSW_MAX_SESSIONS (FR-036). It is the one refusal in this package that is
	// about the host rather than about the request: nothing the caller sent is
	// wrong, there is simply no room, which is why the handler answers 429 and
	// not 400.
	ErrTooManySessions = errors.New("the concurrent-session cap is reached")

	// ErrSessionDead marks an attempt to move a terminal record, and — from
	// Manager.Output — a session the host has just confirmed is no longer there
	// (#21). One sentinel for both, because it is one fact to every caller:
	// dead is the end of the state machine in data-model.md, and a dead session
	// is answered exactly as an id nobody was ever issued is.
	ErrSessionDead = errors.New("session is dead")

	// ErrRestartInFlight refuses a second restart of a session whose process is
	// already being restarted (spec 013, FR-012).
	//
	// It is a refusal about timing rather than about the request: nothing the
	// caller sent is wrong, and trying again in a moment is the right response —
	// which is why it is its own sentinel rather than folded into ErrSessionDead.
	ErrRestartInFlight = errors.New("a restart of this session is already in flight")

	// ErrUnknownStartCommand is a create naming a start command the operator did
	// not configure. It is refused rather than falling back to the default: a
	// caller that asked for remote control and silently got a plain session has
	// no way to discover that is what happened (#38).
	ErrUnknownStartCommand = errors.New("no such start command")

	// ErrInvalidLifetime is a per-session lifetime override the daemon will not
	// grant: past the operator's ceiling, or asking for a session that never
	// expires on a daemon whose ceiling still stands (#37).
	ErrInvalidLifetime = errors.New("invalid session lifetime")

	// ErrCredentialNotPending marks a claim on a session whose credential has
	// already been handed out. It is not reachable through the API — ClaimPending
	// only ever asks about sessions it has just seen are pending — and exists so
	// that a future caller reaching SetCredential twice fails loudly rather than
	// silently invalidating a token somebody is using.
	ErrCredentialNotPending = errors.New("session credential is not pending")

	// ErrInvalidSession wraps every malformed-record rejection from Add.
	ErrInvalidSession = errors.New("invalid session record")

	// ErrInvalidState marks a state value outside the three.
	ErrInvalidState = errors.New("invalid session state")
)

// Store is the in-memory set of session records, safe for concurrent use.

// argument to new-session: if Claude were the session's command, a crash would
// take the tmux session with it and the scrollback that says why. A shell that
// was handed a command line keeps the window — and keeps a prompt for
// milestone 4's device-code relay to type into.
//
// It is a constant, so it never travels through Paste. Paste exists because
// tmux's parser eats a trailing unescaped ";" from caller text (research D4);
// this string is daemon-authored and contains no ";" at all.
const claudeStartCommand = "claude --dangerously-skip-permissions"

// enterKey is tmux's name for the Return key. SendKeys is called without -l so
// that this is looked up as a key rather than sent as five characters, which is
// also why the command above rides in the same call: tmux consumes the
// arguments in order, so one exec both types the line and runs it.
const enterKey = "Enter"

// The Claude CLI's own flags for continuing a conversation (milestone 15).
//
// Long forms rather than -c and -r, because these end up in the command line the
// create form shows the operator and a preview reading `claude -c -r 88e5…` is a
// preview nobody can check against what they asked for.
//
// They are constants in this repository and never configuration: an operator who
// could spell these could put an arbitrary flag on the line that starts an
// unsandboxed shell, which is the execution surface FR-016 keeps closed.
//
// Exported because the create form's preview has to show them and must not spell
// them itself: a script with its own copy is a second speller, free to show an
// operator a flag the daemon stopped passing. The page reads these off the
// daemon exactly as it reads the command lines.

