// withdrawIfStopped reads the session's liveness again after the paste and
// returns non-nil when the Return that would follow must not be pressed.
//
// The window it closes is small and real: a prompt admitted against a running
// harness is delivered to one that exited while it was being delivered, which
// leaves the operator's text on the login shell the harness was typed into. The
// Return would then be a shell running whatever they were about to ask Claude
// to do, unsandboxed, under the daemon's user — the one way this route can turn
// data into a command line.
//
// Three readings and only one withdraws. A stopped row means the harness is
// gone, so the line is cleared and nothing is submitted. Running, unknown, or no
// row at all submits as before: unknown is a session carrying no expectation to
// compare against, and refusing on it would break every session started under a
// build that did not record one.
//
// A failed clear is still a withdrawal. The error says both things, because the
// caller's answer is the same either way and the thing that must not happen is a
// submit — "the clear failed" is not a reason to press Return into the shell the
// clear was for.
func (m *Manager) withdrawIfStopped(ctx context.Context, s Session) error {
	name := s.TmuxName()

	infos, err := m.tmux.List(ctx)
	if err != nil {
		// No Enter and no C-u: a liveness this daemon could not read is not
		// evidence the harness is alive, and the handler's 500 is the honest
		// answer to a prompt whose delivery it cannot account for.
		return fmt.Errorf("re-check session %s after the paste: %w", s.ID, err)
	}

	stopped := false
	for _, info := range infos {
		if info.Name == name {
			stopped = info.Claude == tmuxctl.LivenessStopped
			break
		}
	}
	if !stopped {
		return nil
	}

	if err := m.tmux.SendKeys(ctx, name, clearLineKey); err != nil {
		return fmt.Errorf("withdraw the prompt from session %s: %w: %w", s.ID, ErrSessionNotReady, err)
	}
	return fmt.Errorf("withdraw the prompt from session %s: %w", s.ID, ErrSessionNotReady)
}

