	PanePID(ctx context.Context, name string) (int, error)

	// CaptureHistory returns the scrollback above the visible screen as plain
	// text. Like CapturePane it never passes -e. It refuses with
	// ErrHistoryTooLarge past HistoryLimit lines or 4 MiB rather than returning a
	// shortened history, because a truncated history reads as a complete one.
	CaptureHistory(ctx context.Context, name string) (string, error)

	// Resize sets the session's window to cols by rows, which is how the
	// terminal rather than a stylesheet does the wrapping (#120). tmux rewraps
	// what is already on the screen, so a narrow reader does not wait for the
	// program in the pane to repaint.
	//
	// cols and rows are the only caller-influenced values that reach an argv in
	// this package, so they are clamped here as well as at the handler — see
	// argvResize. A width outside the range is brought inside it, never
	// refused: #120 requires the browser's report to be advisory.
	//
	// **It takes the window out of tmux's automatic sizing, and nothing puts it
	// back.** A resized session no longer follows a terminal that later runs
	// tmux attach on the host, so a caller that offers this must say so.
	Resize(ctx context.Context, name string, cols, rows int) error

	// Kill asks tmux to destroy the session. It is not teardown on its own —
	// callers confirm with Has, because an orphaned session is a live
	// unsandboxed shell with no owner.
	Kill(ctx context.Context, name string) error

	// Has reports whether the session exists. An error means tmux itself
	// failed and the answer is unknown; collapsing that into "gone" would
	// report a teardown that never happened.
	Has(ctx context.Context, name string) (bool, error)

	// List returns every session on the server in one call, which is all
	// startup reconciliation needs. A server that is not running yields an
	// empty slice, not an error — that is the normal first-boot case.
	List(ctx context.Context) ([]SessionInfo, error)

	// ReconcileServerEnvironment makes the tmux server's global environment
	// match the one this daemon composes for a session, in both directions, and
	// returns what it changed.
	//
	// Both directions, because a tmux server hands its global table to every
	// session created on it and keeps it for the server's whole life: a name
	// the server should not have leaks into every new session, and a name it
	// lacks can reach a new session no other way. The second half was missing
	// once and made a shipped fix inert on the one host it was written for —
	// internal/tmuxctl/env.go carries the measurement.
	//
	// On the interface rather than only on *Exec because the daemon must be
	// able to call it at startup without reaching past the abstraction, and
	// because a fake that could not answer it would let a test claim a clean
	// startup path that was never exercised.
	//
	// A server that is not running is not an error: there is nothing to
	// reconcile, and the first session created will start one from a client
	// this package has already given a composed environment.
	ReconcileServerEnvironment(ctx context.Context) (Reconciliation, error)
}

